/**
 * Cron helpers for schedules and reminders. Thin wrapper around `croner`
 * (same package as backend/server) so we keep a stable `parseCron` /
 * `isValidCron` surface for discovery and runners.
 *
 * Standard 5-field expressions (minute hour day-of-month month day-of-week),
 * evaluated in UTC with minute granularity.
 */
import { Cron } from "croner";
function createCroner(source) {
    try {
        return new Cron(source, {
            timezone: "UTC",
            // Schedules/reminders are 5-field; reject 6-field seconds forms.
            legacyMode: true,
        });
    }
    catch (error) {
        throw new Error(`Invalid cron expression "${source}": ${error instanceof Error ? error.message : String(error)}`);
    }
}
/**
 * True when `date`'s UTC minute is a fire time for the expression.
 * Implemented via croner's nextRun from one second before the minute floor.
 */
function matchesCron(cron, date) {
    const floorMs = Math.floor(date.getTime() / 60_000) * 60_000;
    const next = cron.nextRun(new Date(floorMs - 1_000));
    return next !== null && next.getTime() === floorMs;
}
export function parseCron(source) {
    const trimmed = source.trim();
    const parts = trimmed.split(/\s+/);
    if (parts.length !== 5) {
        throw new Error(`Invalid cron expression "${source}": expected 5 fields, got ${parts.length}`);
    }
    const cron = createCroner(trimmed);
    return {
        source: trimmed,
        matches(date) {
            return matchesCron(cron, date);
        },
        nextFire(after = new Date()) {
            const next = cron.nextRun(after);
            if (next === null) {
                throw new Error(`Could not find next fire for cron "${trimmed}" after ${after.toISOString()}`);
            }
            return next;
        },
    };
}
export function isValidCron(source) {
    try {
        parseCron(source);
        return true;
    }
    catch {
        return false;
    }
}
